import React, { useState, useEffect } from 'react';
import { useAuth } from '../utils/AuthContext';
import { businessAPI } from '../utils/api';
import './styles/Profile.css';

export default function GamerProfilePage() {
  const { user } = useAuth();
  const [profile, setProfile] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({});

  useEffect(() => {
    loadProfile();
  }, [user?.id]);

  const loadProfile = async () => {
    try {
      if (user?.id) {
        const response = await businessAPI.getProfile(user.id);
        setProfile(response.data);
        setFormData(response.data);
      }
    } catch (error) {
      console.error('Failed to load profile:', error);
    }
  };

  const handleSaveProfile = async () => {
    try {
      await businessAPI.updateProfile(user.id, formData);
      setProfile(formData);
      setIsEditing(false);
      alert('Profile updated successfully');
    } catch (error) {
      console.error('Failed to save profile:', error);
    }
  };

  const gamerTag = profile?.gamer_tag || user?.username || profile?.email?.split('@')[0] || '';

  if (!profile) {
    return (
      <div className="profile-page">
        <div className="profile-loading">Loading...</div>
      </div>
    );
  }

  return (
    <div className="profile-page">
      <div className="profile-hero">
        <div className="hero-left">
          <div className="hero-avatar" />
        </div>
        <div className="hero-center">
          <button className="hero-tab active">Profile</button>
          <button className="hero-tab">Home</button>
          <button className="hero-tab">Activities</button>
        </div>
        <div className="hero-right">
          <div className="hero-brand">GameLink</div>
        </div>
      </div>

      <div className="profile-title-row">
        <h1>Gamer Profile</h1>
        <div className="profile-title-line" />
      </div>

      <div className="profile-card">
        <div className="profile-card-inner">
          <div className="profile-card-photo">Profile Photo</div>

          <div className="profile-card-content">
            {!isEditing ? (
              <div className="profile-view">
                <div className="profile-grid">
                  <div className="profile-item">
                    <span className="profile-label">First Name</span>
                    <span className="profile-value">{profile.first_name}</span>
                  </div>
                  <div className="profile-item">
                    <span className="profile-label">Second Name</span>
                    <span className="profile-value">{profile.last_name}</span>
                  </div>
                  <div className="profile-item">
                    <span className="profile-label">Gamer Tag</span>
                    <span className="profile-value">{gamerTag}</span>
                  </div>
                  <div className="profile-item">
                    <span className="profile-label">Email</span>
                    <span className="profile-value">{profile.email}</span>
                  </div>
                  <div className="profile-item">
                    <span className="profile-label">Phone</span>
                    <span className="profile-value">{profile.phone_number || '—'}</span>
                  </div>
                  <div className="profile-item">
                    <span className="profile-label">Location</span>
                    <span className="profile-value">{profile.location || '—'}</span>
                  </div>
                </div>
                <div className="profile-actions">
                  <button className="button-primary" onClick={() => setIsEditing(true)}>
                    Edit Profile
                  </button>
                </div>
              </div>
            ) : (
              <div className="profile-edit">
                <div className="profile-edit-fields">
                  <div className="edit-field">
                    <label>First Name</label>
                    <input
                      type="text"
                      value={formData.first_name || ''}
                      onChange={(e) => setFormData({ ...formData, first_name: e.target.value })}
                      placeholder="First Name"
                    />
                  </div>
                  <div className="edit-field">
                    <label>Last Name</label>
                    <input
                      type="text"
                      value={formData.last_name || ''}
                      onChange={(e) => setFormData({ ...formData, last_name: e.target.value })}
                      placeholder="Last Name"
                    />
                  </div>
                  <div className="edit-field">
                    <label>Phone</label>
                    <input
                      type="tel"
                      value={formData.phone_number || ''}
                      onChange={(e) => setFormData({ ...formData, phone_number: e.target.value })}
                      placeholder="Phone"
                    />
                  </div>
                  <div className="edit-field">
                    <label>Location</label>
                    <input
                      type="text"
                      value={formData.location || ''}
                      onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                      placeholder="Location"
                    />
                  </div>
                </div>
                <div className="profile-actions">
                  <button className="button-primary" onClick={handleSaveProfile}>
                    Save changes
                  </button>
                  <button className="button-secondary" onClick={() => setIsEditing(false)}>
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
